import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

import { cn } from "@/lib/utils";

/**
 * Cookie Banner
 *
 * A cookie consent banner with three equal ways out: accept everything,
 * reject everything, or open the options and choose per category. Reject is
 * as easy to reach as accept, which is what GDPR style consent asks for.
 *
 * The choice is saved to localStorage with a version and an expiry. The
 * banner renders nothing on the server and nothing for a visitor who has
 * already chosen, so it never flashes on load. Change `version` to ask
 * everyone again, for example after adding a new category.
 *
 * `useCookieConsent` reads the saved choice anywhere in the app, so scripts
 * can wait for it, and its `reset` brings the banner back (for a "Cookie
 * settings" link in a footer).
 *
 * The cookie in the corner loses a bite when the pointer rests on Accept and
 * two more as the banner leaves. With reduced motion nothing slides and the
 * bites appear at once.
 *
 * The banner is a non-modal dialog: it is labelled, it never traps or steals
 * focus, and every category is a real switch.
 */

export type CookieBannerVariant = "card" | "bar";
export type CookieBannerPosition = "bottom-left" | "bottom-center" | "bottom-right";
export type CookieBannerPlacement = "fixed" | "inline";
export type CookieBannerTone = "neutral" | "blue" | "emerald" | "orange";
export type CookieConsentAction = "accept" | "reject" | "save";

export interface CookieCategory {
  /** Key used in the saved consent, for example "analytics". */
  id: string;
  label: string;
  description?: string;
  /** Always on and not switchable. */
  required?: boolean;
  /** Starting position of the switch. Off unless set. */
  defaultValue?: boolean;
}

/** Category id to allowed or not. */
export type CookieConsent = Record<string, boolean>;

export interface CookieBannerProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title" | "children"> {
  /** A compact corner card or a wide strip along the bottom. */
  variant?: CookieBannerVariant;
  /** Corner the card sits in. The bar is always centred. */
  position?: CookieBannerPosition;
  /** `fixed` pins it to the viewport. `inline` renders it in the page flow. */
  placement?: CookieBannerPlacement;
  /** Colour of the main button and the switches. */
  tone?: CookieBannerTone;
  title?: string;
  description?: React.ReactNode;
  /** Adds a link to your policy after the description. */
  policyHref?: string;
  policyLabel?: string;
  categories?: CookieCategory[];
  acceptLabel?: string;
  rejectLabel?: string;
  customizeLabel?: string;
  saveLabel?: string;
  requiredLabel?: string;
  /** localStorage key. Pass `null` to keep nothing. */
  storageKey?: string | null;
  /** Change it to ask every visitor again. */
  version?: string;
  /** Days before the saved choice expires and the banner returns. */
  expiresDays?: number;
  /** Control visibility yourself. Leave unset to follow the saved choice. */
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Runs once the visitor has chosen. */
  onConsent?: (consent: CookieConsent, action: CookieConsentAction) => void;
  /** The cookie loses bites as the visitor accepts. */
  bite?: boolean;
}

const DEFAULT_STORAGE_KEY = "cookie-consent";
const CHANGE_EVENT = "cookie-banner:change";
const DAY = 86_400_000;
const EASE = [0.32, 0.72, 0, 1] as const;
const EASE_OUT = [0.23, 1, 0.32, 1] as const;

const DEFAULT_CATEGORIES: CookieCategory[] = [
  {
    id: "necessary",
    label: "Necessary",
    description: "Sign in, security and saving this choice.",
    required: true,
  },
  {
    id: "analytics",
    label: "Analytics",
    description: "Anonymous counts of visits and page views.",
  },
  {
    id: "preferences",
    label: "Preferences",
    description: "Remembers settings like theme and language.",
  },
  {
    id: "marketing",
    label: "Marketing",
    description: "Measures ads and limits how often you see them.",
  },
];

interface StoredRecord {
  version: string | null;
  expires: number;
  consent: CookieConsent;
}

function readRecord(storageKey: string, version?: string): StoredRecord | null {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(storageKey);
    if (!raw) return null;
    const record = JSON.parse(raw) as Partial<StoredRecord> | null;
    if (!record || typeof record !== "object" || !record.consent || typeof record.consent !== "object") return null;
    if (typeof record.expires !== "number" || record.expires < Date.now()) return null;
    if (version !== undefined && record.version !== version) return null;
    return record as StoredRecord;
  } catch {
    // Blocked storage or a damaged value: treat as no choice yet.
    return null;
  }
}

function announceChange() {
  window.dispatchEvent(new Event(CHANGE_EVENT));
}

/** The saved choice, or null when the visitor has not chosen (or it expired). */
export function readCookieConsent(storageKey: string = DEFAULT_STORAGE_KEY, version?: string): CookieConsent | null {
  return readRecord(storageKey, version)?.consent ?? null;
}

/**
 * Follows the saved choice from anywhere in the app. `consent` is null until
 * the visitor chooses. `reset` forgets the choice, which brings the banner back.
 */
export function useCookieConsent(storageKey: string = DEFAULT_STORAGE_KEY, version?: string) {
  const [consent, setConsent] = React.useState<CookieConsent | null>(null);

  React.useEffect(() => {
    const sync = () => setConsent(readCookieConsent(storageKey, version));
    sync();
    window.addEventListener(CHANGE_EVENT, sync);
    window.addEventListener("storage", sync);
    return () => {
      window.removeEventListener(CHANGE_EVENT, sync);
      window.removeEventListener("storage", sync);
    };
  }, [storageKey, version]);

  const reset = React.useCallback(() => {
    try {
      window.localStorage.removeItem(storageKey);
    } catch {
      // Nothing was saved if storage is blocked.
    }
    announceChange();
  }, [storageKey]);

  return { consent, reset };
}

/* Hover is light catching the top of the key and falling off down its face. */
const LIGHT_UP = "before:bg-[linear-gradient(180deg,rgba(255,255,255,.2)_0%,rgba(255,255,255,0)_75%)]";

const TONES: Record<CookieBannerTone, { primary: string; switchOn: string; knobOn: string; focus: string }> = {
  neutral: {
    primary: cn(
      "bg-[linear-gradient(180deg,#45454d_0%,#18181b_100%)] text-white",
      "shadow-[inset_0_1px_0_rgba(255,255,255,.2),0_0_0_1px_rgba(0,0,0,.75),0_1px_2px_rgba(0,0,0,.3),0_4px_8px_-4px_rgba(0,0,0,.4)]",
      "dark:bg-[linear-gradient(180deg,#ffffff_0%,#f1f1f3_45%,#d2d2d8_100%)] dark:text-neutral-900",
      "dark:shadow-[inset_0_1px_0_#fff,inset_0_-1px_0_rgba(0,0,0,.18),0_0_0_1px_rgba(0,0,0,.8),0_2px_3px_rgba(0,0,0,.6),0_6px_12px_-6px_rgba(0,0,0,.9)]",
      // Graphite catches light; white cannot brighten, so it dims toward the bottom instead.
      LIGHT_UP,
      "dark:before:bg-[linear-gradient(180deg,rgba(0,0,0,.03)_0%,rgba(0,0,0,.11)_100%)]",
      "active:shadow-[inset_0_2px_4px_rgba(0,0,0,.45),0_0_0_1px_rgba(0,0,0,.75)] dark:active:shadow-[inset_0_2px_5px_rgba(0,0,0,.28),0_0_0_1px_rgba(0,0,0,.8)]",
    ),
    switchOn: "bg-neutral-900 dark:bg-white",
    knobOn:
      "dark:bg-[linear-gradient(180deg,#3d3d44_0%,#18181b_100%)] dark:shadow-[inset_0_1px_0_rgba(255,255,255,.2),0_0_0_1px_rgba(0,0,0,.6),0_1px_2px_rgba(0,0,0,.3)]",
    focus: "focus-visible:outline-neutral-900/60 dark:focus-visible:outline-white/70",
  },
  blue: {
    primary: "bg-[linear-gradient(180deg,#5b9dff_0%,#2f6fed_48%,#1d4ed8_100%)] text-white",
    switchOn: "bg-blue-600 dark:bg-blue-500",
    knobOn: "",
    focus: "focus-visible:outline-blue-600/70 dark:focus-visible:outline-blue-400/80",
  },
  emerald: {
    primary: "bg-[linear-gradient(180deg,#34d399_0%,#10a56f_48%,#047857_100%)] text-white",
    switchOn: "bg-emerald-600 dark:bg-emerald-500",
    knobOn: "",
    focus: "focus-visible:outline-emerald-600/70 dark:focus-visible:outline-emerald-400/80",
  },
  orange: {
    primary: "bg-[linear-gradient(180deg,#fb923c_0%,#f26a1b_48%,#c2410c_100%)] text-white",
    switchOn: "bg-orange-600 dark:bg-orange-500",
    knobOn: "",
    focus: "focus-visible:outline-orange-600/70 dark:focus-visible:outline-orange-400/80",
  },
};

/* Raised edge, hover light and sunk press shared by the coloured main buttons. */
const COLOURED_EDGE =
  LIGHT_UP +
  " active:shadow-[inset_0_2px_4px_rgba(0,0,0,.4),0_0_0_1px_rgba(0,0,0,.3)] dark:active:shadow-[inset_0_2px_4px_rgba(0,0,0,.45),0_0_0_1px_rgba(0,0,0,.8)] " +
  "shadow-[inset_0_1px_0_rgba(255,255,255,.35),inset_0_-1px_0_rgba(0,0,0,.2),0_0_0_1px_rgba(0,0,0,.3),0_1px_2px_rgba(0,0,0,.3),0_4px_8px_-4px_rgba(0,0,0,.4)] dark:shadow-[inset_0_1px_0_rgba(255,255,255,.35),inset_0_-1px_0_rgba(0,0,0,.25),0_0_0_1px_rgba(0,0,0,.8),0_2px_3px_rgba(0,0,0,.6),0_6px_12px_-6px_rgba(0,0,0,.9)]";

const BUTTON_BASE =
  "inline-flex h-9 shrink-0 select-none items-center justify-center whitespace-nowrap rounded-[10px] px-3.5 text-[13px] font-medium outline-none transition-[box-shadow,background-color,color] duration-100 focus-visible:outline-2 focus-visible:outline-offset-2 motion-reduce:transition-none relative isolate before:pointer-events-none before:absolute before:inset-0 before:rounded-[inherit] before:opacity-0 before:transition-opacity before:duration-150 hover:before:opacity-100 motion-reduce:before:transition-none";

const SECONDARY = cn(
  "bg-[linear-gradient(180deg,#ffffff_0%,#f0f0f2_100%)] text-neutral-900",
  "shadow-[inset_0_1px_0_#fff,0_0_0_1px_rgba(0,0,0,.12),0_1px_2px_rgba(0,0,0,.08)]",
  "dark:bg-[linear-gradient(180deg,#2c2c31_0%,#1c1c20_100%)] dark:text-white",
  "dark:shadow-[inset_0_1px_0_rgba(255,255,255,.1),0_0_0_1px_rgba(0,0,0,.85),0_2px_3px_rgba(0,0,0,.5)]",
  "before:bg-[linear-gradient(180deg,rgba(0,0,0,0)_0%,rgba(0,0,0,.05)_100%)] dark:before:bg-[linear-gradient(180deg,rgba(255,255,255,.09)_0%,rgba(255,255,255,.02)_100%)]",
  "active:shadow-[inset_0_1px_3px_rgba(0,0,0,.16),0_0_0_1px_rgba(0,0,0,.12)] dark:active:shadow-[inset_0_2px_5px_rgba(0,0,0,.6),0_0_0_1px_rgba(0,0,0,.85)]",
);

const GHOST =
  "text-neutral-500 hover:bg-black/[0.05] hover:text-neutral-900 dark:text-white/55 dark:hover:bg-white/[0.07] dark:hover:text-white";

const SURFACE = cn(
  "bg-[linear-gradient(180deg,#ffffff_0%,#f8f8f9_100%)] text-neutral-900",
  "shadow-[0_0_0_1px_rgba(0,0,0,.08),0_1px_2px_rgba(0,0,0,.06),0_12px_32px_-12px_rgba(0,0,0,.22)]",
  "dark:bg-[linear-gradient(180deg,#1d1d20_0%,#121214_100%)] dark:text-white",
  "dark:shadow-[inset_0_1px_0_rgba(255,255,255,.09),0_0_0_1px_rgba(0,0,0,.9),0_2px_4px_rgba(0,0,0,.5),0_20px_40px_-16px_rgba(0,0,0,.9)]",
);

const JUSTIFY: Record<CookieBannerPosition, string> = {
  "bottom-left": "justify-start",
  "bottom-center": "justify-center",
  "bottom-right": "justify-end",
};

/* Where each bite lands on the cookie's rim. They overlap, so the edge reads as chewed. */
const BITES = [
  { cx: 25.2, cy: 6.8, r: 5.6 },
  { cx: 29, cy: 16, r: 5 },
  { cx: 26, cy: 24.4, r: 5 },
];

const CHIPS = [
  { cx: 11, cy: 10.5, r: 1.7 },
  { cx: 17.5, cy: 8.5, r: 1.2 },
  { cx: 9.5, cy: 17.5, r: 1.3 },
  { cx: 17.5, cy: 15.5, r: 1.8 },
  { cx: 14, cy: 22.5, r: 1.5 },
  { cx: 20.5, cy: 21, r: 1.1 },
];

function Cookie({ bites, leaving, instant }: { bites: number; leaving: boolean; instant: boolean }) {
  const maskId = `cookie-${React.useId().replace(/:/g, "")}`;

  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 32 32"
      className="mt-0.5 size-7 shrink-0 text-neutral-900 dark:text-white"
    >
      <mask id={maskId} maskUnits="userSpaceOnUse" x="0" y="0" width="32" height="32">
        <rect width="32" height="32" fill="#fff" />
        {CHIPS.map((chip) => (
          <circle key={`${chip.cx}-${chip.cy}`} cx={chip.cx} cy={chip.cy} r={chip.r} fill="#000" />
        ))}
        {BITES.map((spot, index) => {
          const bitten = index < bites;
          // A bite opens from most of its size, never from a point. Resting on Accept takes the
          // first one after a short pause, so a pointer passing over the button changes nothing.
          const transition = instant
            ? { duration: 0 }
            : bitten
              ? { duration: 0.14, ease: EASE_OUT, delay: leaving ? index * 0.05 : 0.06 }
              : { duration: 0.1, ease: EASE_OUT };

          return (
            <motion.circle
              key={spot.cy}
              cx={spot.cx}
              cy={spot.cy}
              fill="#000"
              initial={false}
              animate={{ r: bitten ? spot.r : spot.r * 0.6, opacity: bitten ? 1 : 0 }}
              transition={transition}
            />
          );
        })}
      </mask>
      <circle cx="16" cy="16" r="13" fill="currentColor" mask={`url(#${maskId})`} />
    </svg>
  );
}

function Switch({
  checked,
  onChange,
  tone,
  labelledBy,
  describedBy,
}: {
  checked: boolean;
  onChange: (next: boolean) => void;
  tone: CookieBannerTone;
  labelledBy: string;
  describedBy?: string;
}) {
  const tones = TONES[tone];

  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-labelledby={labelledBy}
      aria-describedby={describedBy}
      onClick={() => onChange(!checked)}
      className={cn(
        "relative mt-0.5 h-5 w-9 shrink-0 rounded-full outline-none transition-colors duration-150 focus-visible:outline-2 focus-visible:outline-offset-2 motion-reduce:transition-none",
        "shadow-[inset_0_1px_2px_rgba(0,0,0,.18)] dark:shadow-[inset_0_1px_2px_rgba(0,0,0,.7),0_1px_0_rgba(255,255,255,.06)]",
        checked ? tones.switchOn : "bg-black/[0.14] dark:bg-white/[0.14]",
        tones.focus,
      )}
    >
      <span
        aria-hidden="true"
        className={cn(
          "absolute left-0.5 top-0.5 size-4 rounded-full transition-transform duration-150 ease-[cubic-bezier(.32,.72,0,1)] motion-reduce:transition-none",
          "bg-[linear-gradient(180deg,#ffffff_0%,#e4e4e8_100%)] shadow-[inset_0_1px_0_#fff,0_0_0_1px_rgba(0,0,0,.22),0_1px_2px_rgba(0,0,0,.3)]",
          checked ? cn("translate-x-4", tones.knobOn) : "translate-x-0",
        )}
      />
    </button>
  );
}

function initialChoices(categories: CookieCategory[]): CookieConsent {
  const choices: CookieConsent = {};
  for (const category of categories) choices[category.id] = Boolean(category.required || category.defaultValue);
  return choices;
}

export function CookieBanner({
  variant = "card",
  position = "bottom-left",
  placement = "fixed",
  tone = "neutral",
  title = "We use cookies",
  description = "Some keep the site working. Others measure traffic and remember your settings, and those are up to you.",
  policyHref,
  policyLabel = "Cookie policy",
  categories = DEFAULT_CATEGORIES,
  acceptLabel = "Accept all",
  rejectLabel = "Reject all",
  customizeLabel = "Customize",
  saveLabel = "Save choices",
  requiredLabel = "Always on",
  storageKey = DEFAULT_STORAGE_KEY,
  version,
  expiresDays = 180,
  open,
  onOpenChange,
  onConsent,
  bite = true,
  className,
  ...rest
}: CookieBannerProps) {
  const reduced = useReducedMotion() ?? false;
  const uid = React.useId();
  const titleId = `${uid}-title`;
  const descriptionId = `${uid}-description`;
  const panelId = `${uid}-options`;

  const [mounted, setMounted] = React.useState(false);
  const [internalOpen, setInternalOpen] = React.useState(false);
  const [expanded, setExpanded] = React.useState(false);
  const [choices, setChoices] = React.useState<CookieConsent>(() => initialChoices(categories));
  const [nearAccept, setNearAccept] = React.useState(false);
  const [eating, setEating] = React.useState(false);
  const commitFrame = React.useRef<number | null>(null);
  const customizeRef = React.useRef<HTMLButtonElement>(null);

  // Follow the saved choice: open when there is none, closed once there is.
  React.useEffect(() => {
    const sync = () => {
      if (storageKey === null) return;
      const record = readRecord(storageKey, version);
      if (record) setChoices((current) => ({ ...current, ...record.consent }));
      setInternalOpen(!record);
    };

    if (storageKey === null) setInternalOpen(true);
    else sync();
    setMounted(true);

    window.addEventListener(CHANGE_EVENT, sync);
    window.addEventListener("storage", sync);
    return () => {
      window.removeEventListener(CHANGE_EVENT, sync);
      window.removeEventListener("storage", sync);
    };
  }, [storageKey, version]);

  React.useEffect(
    () => () => {
      if (commitFrame.current !== null) window.cancelAnimationFrame(commitFrame.current);
    },
    [],
  );

  const visible = mounted && (open ?? internalOpen);

  // Each time the banner returns it starts collapsed with a whole cookie.
  React.useEffect(() => {
    if (!visible) return;
    setExpanded(false);
    setEating(false);
    setNearAccept(false);
  }, [visible]);

  const commit = (action: CookieConsentAction) => {
    const consent: CookieConsent = {};
    for (const category of categories) {
      if (category.required) consent[category.id] = true;
      else if (action === "accept") consent[category.id] = true;
      else if (action === "reject") consent[category.id] = false;
      else consent[category.id] = Boolean(choices[category.id]);
    }

    setChoices(consent);
    setInternalOpen(false);

    if (storageKey !== null) {
      try {
        const record: StoredRecord = {
          version: version ?? null,
          expires: Date.now() + expiresDays * DAY,
          consent,
        };
        window.localStorage.setItem(storageKey, JSON.stringify(record));
      } catch {
        // Storage is blocked: the choice still applies for this visit.
      }
      announceChange();
    }

    onConsent?.(consent, action);
    onOpenChange?.(false);
  };

  const choose = (action: CookieConsentAction) => {
    if (commitFrame.current !== null) return;
    // Accepting closes on the next frame, so the last bites are drawn and land as the banner leaves.
    if (action === "accept" && bite) {
      setEating(true);
      commitFrame.current = window.requestAnimationFrame(() => {
        commitFrame.current = null;
        commit("accept");
      });
      return;
    }
    commit(action);
  };

  // Escape folds the options away again and returns focus to the button that opened them.
  const onKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    rest.onKeyDown?.(event);
    if (event.key !== "Escape" || !expanded || event.defaultPrevented) return;
    setExpanded(false);
    customizeRef.current?.focus();
  };

  const tones = TONES[tone];
  const isBar = variant === "bar";
  const bites = !bite ? 0 : eating ? BITES.length : nearAccept ? 1 : 0;

  const actions = (
    <div className={cn("flex flex-wrap items-center gap-2", isBar ? "shrink-0 max-md:w-full" : "mt-5")}>
      {/* The quiet button opens the options, then saves them. Reject and Accept never move. */}
      <button
        ref={customizeRef}
        type="button"
        aria-expanded={expanded ? undefined : false}
        aria-controls={expanded ? undefined : panelId}
        onClick={() => (expanded ? choose("save") : setExpanded(true))}
        className={cn(
          BUTTON_BASE,
          GHOST,
          tones.focus,
          "-ml-2 px-2",
          isBar && "md:mr-1",
          expanded && "text-neutral-900 dark:text-white",
        )}
      >
        <span className="relative">{expanded ? saveLabel : customizeLabel}</span>
      </button>
      <div className={cn("ml-auto flex gap-2", isBar ? "max-md:grow" : "max-sm:grow")}>
        <button
          type="button"
          onClick={() => choose("reject")}
          className={cn(BUTTON_BASE, SECONDARY, tones.focus, isBar ? "max-md:flex-1" : "max-sm:flex-1")}
        >
          <span className="relative">{rejectLabel}</span>
        </button>
        <button
          type="button"
          onClick={() => choose("accept")}
          onPointerEnter={() => setNearAccept(true)}
          onPointerLeave={() => setNearAccept(false)}
          onFocus={() => setNearAccept(true)}
          onBlur={() => setNearAccept(false)}
          className={cn(
            BUTTON_BASE,
            tones.primary,
            tone !== "neutral" && COLOURED_EDGE,
            tones.focus,
            isBar ? "max-md:flex-1" : "max-sm:flex-1",
          )}
        >
          <span className="relative">{acceptLabel}</span>
        </button>
      </div>
    </div>
  );

  const options = (
    <AnimatePresence initial={false}>
      {expanded ? (
        <motion.div
          key="options"
          id={panelId}
          initial={{ height: 0, opacity: 0 }}
          animate={{ height: "auto", opacity: 1 }}
          exit={{ height: 0, opacity: 0 }}
          transition={
            reduced
              ? { duration: 0 }
              : { height: { duration: 0.24, ease: EASE }, opacity: { duration: 0.16, ease: "easeOut" } }
          }
          className="overflow-hidden"
        >
          <ul className={cn("pt-5", isBar ? "grid gap-x-10 gap-y-4 sm:grid-cols-2" : "flex flex-col gap-4")}>
            {categories.map((category) => {
              const labelId = `${uid}-${category.id}-label`;
              const detailId = category.description ? `${uid}-${category.id}-detail` : undefined;

              return (
                <li key={category.id} className="flex items-start justify-between gap-5">
                  <div className="min-w-0">
                    <p id={labelId} className="text-[13.5px] font-medium leading-5">
                      {category.label}
                    </p>
                    {category.description ? (
                      <p id={detailId} className="mt-0.5 text-pretty text-[13px] leading-[1.45] text-neutral-500 dark:text-white/50">
                        {category.description}
                      </p>
                    ) : null}
                  </div>
                  {category.required ? (
                    <span className="shrink-0 text-[12.5px] leading-5 text-neutral-500 dark:text-white/50">{requiredLabel}</span>
                  ) : (
                    <Switch
                      checked={Boolean(choices[category.id])}
                      onChange={(next) => setChoices((current) => ({ ...current, [category.id]: next }))}
                      tone={tone}
                      labelledBy={labelId}
                      describedBy={detailId}
                    />
                  )}
                </li>
              );
            })}
          </ul>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );

  const intro = (
    <div className="flex min-w-0 flex-1 items-start gap-3.5">
      <Cookie bites={bites} leaving={eating} instant={reduced} />
      <div className="min-w-0">
        <h2 id={titleId} className="text-[15px] font-semibold leading-5 tracking-[-0.01em]">
          {title}
        </h2>
        <p id={descriptionId} className="mt-1 text-pretty text-[13.5px] leading-[1.5] text-neutral-600 dark:text-white/60">
          {description}
          {policyHref ? (
            <>
              {" "}
              <a
                href={policyHref}
                className={cn(
                  "rounded-sm text-neutral-900 underline decoration-black/25 underline-offset-[3px] outline-none transition-colors duration-150 hover:decoration-black/60 focus-visible:outline-2 focus-visible:outline-offset-2 dark:text-white dark:decoration-white/30 dark:hover:decoration-white/70",
                  tones.focus,
                )}
              >
                {policyLabel}
              </a>
            </>
          ) : null}
        </p>
      </div>
    </div>
  );

  return (
    <AnimatePresence>
      {visible ? (
        <motion.div
          key="cookie-banner"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0, transition: { duration: reduced ? 0 : 0.18, ease: "easeOut" } }}
          transition={{ duration: reduced ? 0 : 0.22, ease: "easeOut" }}
          className={cn(
            "flex font-sans",
            isBar ? "justify-center" : JUSTIFY[position],
            placement === "fixed" ? "pointer-events-none fixed inset-x-0 bottom-0 z-50 p-3 sm:p-4" : "w-full",
          )}
        >
          <motion.div
            {...(rest as React.ComponentProps<typeof motion.div>)}
            role="dialog"
            aria-modal="false"
            aria-labelledby={titleId}
            aria-describedby={descriptionId}
            onKeyDown={onKeyDown}
            initial={{ y: reduced ? 0 : 8 }}
            animate={{ y: 0 }}
            exit={{ y: reduced ? 0 : 8, transition: { duration: reduced ? 0 : 0.18, ease: EASE_OUT } }}
            transition={{ duration: reduced ? 0 : 0.28, ease: EASE }}
            className={cn(
              "pointer-events-auto w-full",
              isBar ? "max-w-[880px] rounded-[18px] p-4 sm:p-5" : "max-w-[384px] rounded-[18px] p-5",
              SURFACE,
              className,
            )}
          >
            {isBar ? (
              <>
                <div className="flex flex-col gap-4 md:flex-row md:items-center md:gap-8">
                  {intro}
                  {actions}
                </div>
                {options}
              </>
            ) : (
              <>
                {intro}
                {options}
                {actions}
              </>
            )}
          </motion.div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}
